import { useEffect, useState } from "react";

export default function Main() {
  const [amount, setAmount] = useState(0);
  const [firstCurrency, setFirstCurrency] = useState("USD");
  const [secondCurrency, setSecondCurrency] = useState("USD");
  const [currencies, setCurrencies] = useState([]);

  const result = amount;

  useEffect(function () {
    async function getCurrencies() {
      const res = await fetch("https://api.frankfurter.dev/v2/currencies");
      const currs = await res.json();

      const isoCodes = currs.map((currency) => currency.iso_code);

      setCurrencies(isoCodes);
    }

    getCurrencies();
  }, []);

  useEffect(
    function () {
      async function getResult() {
        const api = "https://api.frankfurter.dev";
        const res = fetch(`${api}/v2/rate/${firstCurrency}/${secondCurrency}`)
          .then((r) => r.json())
          .then((d) => (amount * d.rate).toFixed(2));

        result = res;
      }
    },
    [firstCurrency, secondCurrency, amount],
  );

  return (
    <div className="main">
      <div>
        <input
          type="number"
          name="amount"
          value={amount}
          onChange={(e) => setAmount(Number(e.target.value))}
        />
        <select
          value={firstCurrency}
          onChange={(e) => setFirstCurrency(e.target.value)}
        >
          {currencies.map((cur) => (
            <option value={cur}>{cur}</option>
          ))}
        </select>
        <button>
          <svg
            viewBox="0 0 24 24"
            width="36"
            height="24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M21 7.5L8 7.5M21 7.5L16.6667 3M21 7.5L16.6667 12"
              stroke="#000000"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              d="M4 16.5L17 16.5M4 16.5L8.33333 21M4 16.5L8.33333 12"
              stroke="#000000"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      </div>

      <div className="left-line">
        <select
          value={secondCurrency}
          onChange={(e) => setSecondCurrency(e.target.value)}
        >
          {currencies.map((cur) => (
            <option value={cur}>{cur}</option>
          ))}
        </select>
        <input disabled={true} value={result} />
      </div>
    </div>
  );
}
